#include <cstddef>

int count_positive(const int values[]) {
    std::size_t n = sizeof(values) / sizeof(values[0]);
    int found = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (values[i] > 0) ++found;
    }
    return found;
}

